import React, { useState } from "react";
import ChatInput from "./components/ChatInput";
import MessageList from "./components/MessageList";
import ChartView from "./components/ChartView";
import TableView from "./components/TableView";
import { queryBackend, uploadFile } from "./api";

export default function App(){
  const [messages, setMessages] = useState([]);
  const [chartData, setChartData] = useState(null);
  const [tableData, setTableData] = useState([]);
  const [loading, setLoading] = useState(false);

  const sendQuery = async (text) => {
    if(!text) return;
    setMessages(m => [...m, {from:"user", text}]);
    setLoading(true);
    try{
      const data = await queryBackend(text);
      setMessages(m => [...m, {from:"bot", text: data.summary || "No summary"}]);
      setChartData(data.chart);
      setTableData(data.table || []);
    }catch(err){
      setMessages(m => [...m, {from:"bot", text: "Error contacting server."}]);
      console.error(err);
    } finally { setLoading(false); }
  };

  const handleUpload = async (file) => {
    try {
      const res = await uploadFile(file);
      alert("Upload success: " + JSON.stringify(res));
    } catch (e) {
      alert("Upload failed");
    }
  };

  return (
    <div className="app-shell container">
      <div className="row">
        <div className="col-md-6">
          <h3>Real Estate Analysis Chatbot</h3>
          <div className="chat-box">
            <MessageList messages={messages} />
          </div>
          <ChatInput onSend={sendQuery} onUpload={handleUpload} loading={loading} />
        </div>

        <div className="col-md-6">
          <div className="table-card mb-3">
            <h5>Chart</h5>
            <ChartView chartData={chartData} />
          </div>
          <div className="table-card">
            <h5>Filtered Table</h5>
            <TableView rows={tableData} />
          </div>
        </div>
      </div>
    </div>
  );
}
